Q: adding variables as numbers not working. looking for what I&#39;m missing, not just what the answer is A: <p>@mokayG's excellent answer gives you the reason. I shouldn't do this, but couldn't resist restructuring your code. Note:</p>
<ul>
<li>No need to use <code>&lt;form&gt;</code> here</li>
<li>Don't use inline handling (<code>onclick=&quot;...&quot;</code>)</li>
<li>Use <a href="https://javascript.info/event-delegation" rel="nofollow noreferrer">event delegation</a></li>
<li>Indent HTML/JS for readability</li>
<li>Use <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Conditional_operator" rel="nofollow noreferrer">ternaries</a> for simple <code>if ... else</code> conditions</li>
<li>Use css for the table/fields</li>
<li>Use <code>colspan</code> for consecutive multiple empty table cells</li>
<li>In this snippet <code>+[some value]</code> is used to convert a string to <code>Number</code>. If you don't trust <code>+[some value]</code> to return a <code>Number</code> you should do more checks on that.</li>
</ul>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>document.addEventListener(`click`, handle);

function handle(evt) {
  if (evt.target.id === `calc`) {
    return calculateSum();
  }

  return true;
}

function calculateSum() {
  const fields = [...document.querySelectorAll(`input`)]
    .reduce((acc, input) =&gt; ({...acc, [input.id]: input}), {});

  fields.unloadedtotal.value = fields.unloadedcheck.checked 
    ? +fields.unloadedrate.value * +fields.unloadedmiles.value
    : 0;
  fields.locktotal.value = fields.lockcheck.checked
    ? fields.lockfee.value
    : 0;


  fields.subtotal.value = 
    +fields.unloadedtotal.value + +fields.locktotal.value;
  fields.subtotal2.value = 
    +fields.unloadedtotal.value * +fields.locktotal.value;
}</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>input[type="number"] {
  width: 5em;
  text-align: right
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;table&gt;
  &lt;tr&gt;
    &lt;td&gt;UNLOADED&lt;/td&gt;
    &lt;td&gt;&lt;input type="checkbox" id="unloadedcheck" checked&gt;&lt;/td&gt;
    &lt;td&gt;&lt;input type="number" id="unloadedrate" value="3"&gt;&lt;/td&gt;
    &lt;td&gt;&lt;input type="number" id="unloadedmiles" value="10"&gt;&lt;/td&gt;
    &lt;td&gt;&lt;input type="number" id="unloadedtotal"&gt;&lt;/td&gt;
  &lt;/tr&gt;
  &lt;tr&gt;
    &lt;td&gt;LOCK&lt;/td&gt;
    &lt;td&gt;&lt;input type="checkbox" id="lockcheck" checked&gt;&lt;/td&gt;
    &lt;td&gt;&lt;input type="number" id="lockfee" value="65"&gt;&lt;/td&gt;
    &lt;td&gt;&lt;/td&gt;
    &lt;td&gt;&lt;input type="number" id="locktotal"&gt;&lt;/td&gt;
  &lt;/tr&gt;
  &lt;tr&gt;
    &lt;td colspan="4"&gt;SUBTOTAL (add)&lt;/td&gt;
    &lt;td&gt;&lt;input type="number" id="subtotal"&gt;&lt;/td&gt;
  &lt;/tr&gt;
  &lt;tr&gt;
    &lt;td colspan="4"&gt;SUBTOTAL (multiple)&lt;/td&gt;
    &lt;td&gt;&lt;input type="number" id="subtotal2"&gt;&lt;/td&gt;
  &lt;/tr&gt;
&lt;/table&gt;

&lt;button id="calc"&gt;CALCULATE &lt;/button&gt;</code></pre>
</div>
</div>
</p>
